class Solution {
    vector<int> tasks,workers;
    int pills,strength;
    bool can(int count){
        multiset<int> available(workers.end()-count,workers.end());
        int remainingPills=pills;
        for(int task=count-1;task>=0;--task){
            auto worker=available.lower_bound(tasks[task]);
            if(worker!=available.end())available.erase(worker);
            else{
                if(!remainingPills)return false;
                worker=available.lower_bound(tasks[task]-strength);
                if(worker==available.end())return false;
                --remainingPills;
                available.erase(worker);
            }
        }
        return true;
    }
    public: int maxTaskAssign(vector<int>& tasks,vector<int>& workers,int pills,int strength){
        sort(tasks.begin(),tasks.end());
        sort(workers.begin(),workers.end());
        this->tasks=tasks;
        this->workers=workers;
        this->pills=pills;
        this->strength=strength;
        int left=0,right=min(tasks.size(),workers.size());
        while(left<right){
            int middle=(left+right+1)/2;
            if(can(middle))left=middle;
            else right=middle-1;
        }
        return left;
    }
};
